/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.util.List;
import java.util.Locale;

/**
 * Order of the log levels, so a minimum level can be applied whatever the origin calls them.
 */
public final class Levels {

  private static final List<String> ORDER =
      List.of("TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL");

  private Levels() {}

  /** TRACE, DEBUG, INFO, WARN, ERROR or FATAL for the names used by the loggers and OTLP. */
  public static String normalize(final String level) {
    if (null == level || level.isBlank()) {
      return "INFO";
    }
    String upper = level.trim().toUpperCase(Locale.ROOT);
    if (upper.startsWith("WARN")) {
      return "WARN";
    }
    if (upper.startsWith("ERR") || "SEVERE".equals(upper)) {
      return "ERROR";
    }
    if (upper.startsWith("FATAL") || upper.startsWith("CRIT")) {
      return "FATAL";
    }
    if (upper.startsWith("DEBUG") || "FINE".equals(upper) || "CONFIG".equals(upper)) {
      return "DEBUG";
    }
    if (upper.startsWith("TRACE") || upper.startsWith("FINE")) {
      return "TRACE";
    }
    return ORDER.contains(upper) ? upper : "INFO";
  }

  /** @return true if {@code level} is at least {@code minimum} */
  public static boolean atLeast(final String level, final String minimum) {
    return ORDER.indexOf(normalize(level)) >= ORDER.indexOf(normalize(minimum));
  }

  /** Level for an OTLP severity number (1-24). */
  public static String fromSeverity(final int severity) {
    if (severity >= 21) {
      return "FATAL";
    }
    if (severity >= 17) {
      return "ERROR";
    }
    if (severity >= 13) {
      return "WARN";
    }
    if (severity >= 9) {
      return "INFO";
    }
    if (severity >= 5) {
      return "DEBUG";
    }
    return severity >= 1 ? "TRACE" : "INFO";
  }
}
